                AutoAimComp.UpdateAiming = function(self, ...)
                    if _G.XthrlenConfig.CustomAimbot or _G.XthrlenConfig.AimTouchEnable then
                        -- Randomize speed factor: 0.8 ~ 1.2 of configured value
