                ["CheckReportSecAttackFlow"]=1,
                ["CheckReportSecAttackFlowWithAttackFlow"]=1,
            }
            NetUtil.SendPacket = function(packetName, ...)
                if blockedShootPackets[packetName] then return nil end
                return origSend(packetName, ...)
